package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.village.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes; import net.minecraft.world.level.block.Blocks;
public final class VillageStorageGameTest{@GameTest public void storageObservationReadsRealContainer(GameTestHelper c){c.setBlock(2,1,2,Blocks.CHEST);c.spawn(EntityTypes.VILLAGER,2,1,3);c.runAtTickTime(2,()->{TheWorldRemembers.processWorld(c.getLevel());var vs=VillageManager.get(c.getLevel().getServer()).all();if(vs.isEmpty()){c.fail("No village observed");return;}var s=VillageStorageManager.get(c.getLevel().getServer()).get(vs.iterator().next().villageId());if(s==null||s.containers()<1||s.capacitySlots()<27){c.fail("Real chest was not observed");return;}c.succeed();});}}
